import{L as u}from"./chunks/LessonQuiz.a2e1a013.js";import{d as T,o as a,c as e,k as t,F as n,D as v,H as p,Q as h,t as c,e as i,p as m,m as k,_ as g}from"./chunks/framework.68eebb55.js";const d=o=>(m("data-v-2e501212"),o=o(),k(),o),b={class:"lesson"},f=d(()=>t("div",{class:"meta"},[t("span",{class:"tag"},"第 01 / 40 篇"),t("span",null,"第一阶段：AI 与大模型基础"),t("span",null,"阅读约 8 分钟")],-1)),I=d(()=>t("h1",null,"ChatGPT 到底是如何回答问题的？",-1)),P=d(()=>t("p",null,"当你向 ChatGPT 提问「为什么 JavaScript 是单线程的？」时，模型不是简单查询固定答案，而是根据上下文预测下一个 Token。",-1)),L=d(()=>t("h2",null,"一、ChatGPT 的生成流程",-1)),y={class:"visual"},C=d(()=>t("strong",null,"自回归生成（简化）",-1)),q={class:"step"},G={key:0,class:"arrow"},w=h(`<p data-v-2e501212>这个过程叫 Autoregressive Generation。现代聊天产品还可能结合搜索、工具调用和记忆等能力。</p><h2 data-v-2e501212>二、Token 是什么？</h2><p data-v-2e501212>Token 是模型处理文本的基本单位，不一定等于一个汉字或英文单词。</p><pre data-v-2e501212><code data-v-2e501212>输入：我是一名前端开发工程师
示意分词：[&quot;我&quot;,&quot;是一名&quot;,&quot;前端&quot;,&quot;开发&quot;,&quot;工程师&quot;]
示意 ID：[123,456,789,234,567]</code></pre><p data-v-2e501212>以上仅为示意。Token ID 是编号，本身不直接表达语义。</p><h2 data-v-2e501212>三、模型如何生成回答？</h2><p data-v-2e501212>假设输入「JavaScript 是一种」，模型可能计算以下候选 Token 概率：</p><table data-v-2e501212><thead data-v-2e501212><tr data-v-2e501212><th data-v-2e501212>候选</th><th data-v-2e501212>假设概率</th></tr></thead><tbody data-v-2e501212><tr data-v-2e501212><td data-v-2e501212>编程</td><td data-v-2e501212>65%</td></tr><tr data-v-2e501212><td data-v-2e501212>脚本</td><td data-v-2e501212>20%</td></tr><tr data-v-2e501212><td data-v-2e501212>动态</td><td data-v-2e501212>10%</td></tr><tr data-v-2e501212><td data-v-2e501212>其他</td><td data-v-2e501212>5%</td></tr></tbody></table><p data-v-2e501212>选中「编程」后，模型继续预测「语言」等后续 Token。Temperature、Top-p 等参数影响选择策略，模型并非每次都取概率最大的 Token。</p><h2 data-v-2e501212>四、Transformer 与 Attention</h2><p data-v-2e501212>Transformer 是现代大语言模型常用架构。Attention 让模型处理一个位置时可以利用上下文。</p><div class="visual" data-v-2e501212><strong data-v-2e501212>上下文指代示意</strong><p data-v-2e501212>小明把电脑放在桌子上，因为它太重了。</p><div class="cols" data-v-2e501212><div class="panel" data-v-2e501212>电脑：候选指代对象</div><div class="panel" data-v-2e501212>桌子：候选指代对象</div></div><p data-v-2e501212>模型结合上下文学习关联，而不是执行硬编码关键词规则。</p></div><h2 data-v-2e501212>五、为什么模型能回答编程问题？</h2><p data-v-2e501212>模型在训练中学习了大量语言和代码模式，因此可以生成：</p><pre data-v-2e501212><code data-v-2e501212>const sum = (a: number, b: number) =&gt; a + b;</code></pre><p data-v-2e501212><strong data-v-2e501212>生成看起来正确的代码，不代表代码一定正确。</strong>实际工程仍需测试和人工审查。</p><h2 data-v-2e501212>六、React + Node.js 聊天系统</h2>`,17),N={class:"visual"},S={class:"step"},A={key:0,class:"arrow"},D=h("<p data-v-2e501212>聊天应用还需要会话存储、流式输出、权限、限流和安全机制。<strong data-v-2e501212>聊天机器人应用不等于 LLM 本身。</strong></p><h2 data-v-2e501212>七、知识总结</h2><table data-v-2e501212><thead data-v-2e501212><tr data-v-2e501212><th data-v-2e501212>概念</th><th data-v-2e501212>作用</th></tr></thead><tbody data-v-2e501212><tr data-v-2e501212><td data-v-2e501212>LLM</td><td data-v-2e501212>语言生成模型</td></tr><tr data-v-2e501212><td data-v-2e501212>Token</td><td data-v-2e501212>文本处理单位</td></tr><tr data-v-2e501212><td data-v-2e501212>Tokenizer</td><td data-v-2e501212>文本转 Token ID</td></tr><tr data-v-2e501212><td data-v-2e501212>Transformer</td><td data-v-2e501212>序列上下文计算</td></tr><tr data-v-2e501212><td data-v-2e501212>Attention</td><td data-v-2e501212>聚合相关上下文信息</td></tr></tbody></table><h2 data-v-2e501212>学习疑问与解答</h2><p data-v-2e501212>本篇暂无新增问题，后续持续补充。</p>",5),x=d(()=>t("h3",null,"思考题",-1)),j=d(()=>t("p",null,"为什么 ChatGPT 有时会一本正经地给出错误答案？提示：预测高概率 Token 和验证事实真实性之间有什么区别？",-1)),z=d(()=>t("footer",null,[t("span",null,"第 01 篇"),t("a",{href:"./02-token-and-embedding"},"下一篇 →")],-1)),M=T({__name:"ChatGPTLesson",setup(o){return(_,l)=>(a(),e("article",b,[f,I,P,L,t("div",y,[C,(a(),e(n,null,v(["用户输入","Tokenization：文本切分","Token ID 与向量表示","Transformer 模型计算","计算下一个 Token 的概率","选择下一个 Token","重复生成直到结束"],(s,r)=>(a(),e(n,{key:s},[t("div",q,c(s),1),r<6?(a(),e("div",G,"↓")):i("",!0)],64))),64))]),w,t("div",N,[(a(!0),e(n,null,v(["React UI：用户输入","Node.js API：鉴权与组装 Messages","LLM API：Tokenization 与生成","Node.js：转发流式响应","React UI：实时展示回答"],(s,r)=>(a(),e(n,{key:s},[t("div",S,c(s),1),r<4?(a(),e("div",A,"↓")):i("",!0)],64))),128))]),D,p(u,{chapter:1}),x,j,z]))}});const V=g(M,[["__scopeId","data-v-2e501212"]]),U=JSON.parse('{"title":"01 · ChatGPT 到底是如何回答问题的？","description":"","frontmatter":{"title":"01 · ChatGPT 到底是如何回答问题的？","outline":"deep"},"headers":[],"relativePath":"guide/ai/chatbot-course/01-how-chatgpt-works.md","filePath":"guide/ai/chatbot-course/01-how-chatgpt-works.md","lastUpdated":1792049759000}'),B={name:"guide/ai/chatbot-course/01-how-chatgpt-works.md"},F=Object.assign(B,{setup(o){return(_,l)=>(a(),e("div",null,[p(V)]))}});export{U as __pageData,F as default};
